// Article content and native many_to_many tags are saved in one transaction.
function wikiApi(api) {
  async function all(path) {
    let page = 1, items = [];
    while (true) {
      const result = await api.get(path + '/list', { query: { page, page_size: 100 } });
      items = items.concat(result.items);
      if (items.length >= result.total) return items;
      if (!result.items.length) throw new Error('分页数据发生变化，请刷新重试。');
      page++;
    }
  }
  async function treePage(path, request = {}) {
    let cursor, records = [];
    do {
      const result = await api.get(path, { ...request, query: { ...request.query, limit: 100, ...(cursor ? { cursor } : {}) } });
      records = records.concat(result.items);
      cursor = result.has_more ? result.next_cursor : null;
      if (result.has_more && !cursor) throw new Error('目录分页缺少后续游标，请刷新重试。');
    } while (cursor);
    return records;
  }
  async function loadTree() {
    const roots = await treePage(NODES + '/tree/roots');
    const groups = await Promise.all(roots.map(async root => [root, ...(await treePage(NODES + '/tree/descendants/{id}', { path: { id: root.id } })).map(item => item.record)]));
    return groups.flat();
  }
  return {
    tree: loadTree,
    children: parent_id => parent_id ? treePage(NODES + '/tree/children/{id}', { path: { id: parent_id } }) : treePage(NODES + '/tree/roots'),
    tags: () => all(TAGS),
    get: id => api.get(NODES + '/get/{id}', { path: { id } }),
    create: body => api.post(NODES + '/create', { body }),
    update: (id, body) => api.patch(NODES + '/update/{id}', { path: { id }, body }),
    move: (id, body) => api.post(NODES + '/tree/move/{id}', { path: { id }, body }),
    createTag: body => api.post(TAGS + '/create', { body })
  };
}

