            const target = byId.get(info.node.key), id = info.dragNode.key;
            if (!info.dropToGap) move(id, target.id);
            else { const position = info.dropPosition - Number(info.node.pos.split('-').pop()); move(id, target.parent_id || null, position < 0 ? { before_id: target.id } : { after_id: target.id }); }
          }} />}
        </div>
        {dragging && <div className="wiki-root-drop" onDragOver={event => event.preventDefault()} onDrop={event => { event.preventDefault(); move(dragging, null); }}>拖到此处移回根目录</div>}
        {(error || moving) && <div className="wiki-toolbar"><span className="wiki-status">{moving ? '正在移动…' : '加载失败'}</span>{error && <Button size="small" icon={<ReloadOutlined />} onClick={() => { if (pendingMove.current) { if (!moving) refreshMovedSiblings(); } else if (selected?.node_type === 'article' && !article) select(selectedId); else refresh(!nodes.length).catch(() => {}); }}>重试</Button>}</div>}
      </aside>);
  const content = (      <main className="wiki-main">
        {compact && draft && <div className="wiki-edit-actions"><Button type="text" disabled={saving} onClick={() => guard(closeEditor)}>取消</Button><strong>编辑文档</strong><Button type="primary" style={primary} loading={saving} disabled={!editorReady || tagBusy} onClick={save}>保存</Button></div>}
        <div className="wiki-path"><Breadcrumb items={breadcrumb} />{compact && <Button type="text" style={{ border: 0, boxShadow: 'none', background: 'transparent' }} aria-label="打开目录" aria-expanded={navigationOpen} aria-controls="wiki-navigation" icon={<UnorderedListOutlined />} onClick={() => setNavigationOpen(true)} />}</div>
        {error && <Alert className="wiki-error" type="error" showIcon title={error} />}
        {draft ? <div className="wiki-editor">
          <div className="wiki-editor-top"><Input className="wiki-editor-title" aria-label="文章标题" placeholder="文章标题" value={draft.title} maxLength={300} onChange={event => change('title', event.target.value)} disabled={saving} size="large" />{!compact && <><Button disabled={saving} onClick={() => guard(closeEditor)}>取消</Button><Button type="primary" style={primary} loading={saving} disabled={!editorReady || tagBusy} onClick={save}>保存</Button></>}</div>
          {saveError && <Alert className="wiki-error" type="error" showIcon title={saveError} />}
          <div className="wiki-field"><label>标签</label><div className="wiki-field-content"><Select aria-label="文章标签" mode="multiple" showSearch searchValue={tagSearch} onSearch={value => { setTagSearch(value); setQuickTagError(''); }} style={{ width: '100%' }} placeholder="搜索标签，无匹配时回车创建" value={draft.tags} onChange={value => { change('tags', value); setTagSearch(''); }} disabled={saving} loading={tagBusy} filterOption={(input, option) => normalizeTag(option.label).includes(normalizeTag(input))} options={tags.map(tag => ({ value: tag.id, label: tag.name }))} onInputKeyDown={event => { if (event.key === 'Enter' && !event.nativeEvent.isComposing && event.nativeEvent.keyCode !== 229 && tagSearch.trim() && matchingTags.length === 0) { event.preventDefault(); event.stopPropagation(); void quickCreateTag(); } }} notFoundContent={tagSearch.trim() ? '按回车创建“' + tagSearch.trim() + '”' : '暂无标签'} popupRender={menu => <>{menu}<div className="wiki-tag-create"><Button type="text" icon={<PlusOutlined />} onClick={() => { setTagName(tagSearch.trim()); setTagError(''); setTagDialog(true); }}>创建标签</Button></div></>} />{quickTagError && <Alert type="error" showIcon title={quickTagError} />}</div></div>
          <div className="wiki-field"><label>摘要</label><Input.TextArea aria-label="文章摘要" className="wiki-field-content" placeholder="简要描述这篇文章" value={draft.summary} onChange={event => change('summary', event.target.value)} autoSize={{ minRows: 2, maxRows: 4 }} maxLength={500} showCount disabled={saving} /></div>
          <div className="wiki-editor-body" inert={saving || undefined}><VditorEditor className="wiki-vditor" key={draft.id || 'new'} api={ctx.api} ariaLabel="Wiki Markdown 编辑器" value={initialContent.current} height={compact ? 320 : 480} mode="ir" previewMode="editor" outline={false} placeholder="开始记录你的想法…" onReady={value => { editor.current = value; if (value) editorBaseline.current = value.getValue(); setEditorReady(!!value); }} onChange={value => { if (draftRef.current) draftRef.current = { ...draftRef.current, content_md: value === editorBaseline.current ? initialContent.current : value }; }} /></div>
        </div> : detailBusy || (loading && !nodes.length) ? <div className="wiki-empty"><Spin size="large" /></div> : article ? <article>
          <div className="wiki-heading"><div><h1>{article.title}</h1><div className="wiki-tags">{tags.filter(tag => article.tags.includes(tag.id)).map(tag => <Tag key={tag.id} color={tag.color || 'green'} className="wiki-read-tag" style={tagStyle(tag.color)}>{tag.name}</Tag>)}</div></div><Button type="primary" style={primary} icon={<EditOutlined />} onClick={() => beginEdit(article)}>编辑</Button></div>
          <blockquote className="wiki-summary" aria-label="摘要"><p>{article.summary || ''}</p></blockquote>
          <div className="wiki-markdown"><VditorPreview value={article.content_md || ''} ariaLabel="Wiki 文档正文" /></div>
        </article> : selected?.node_type === 'folder' ? <div><div className="wiki-heading"><h1>{selected.title}</h1><Button icon={<EditOutlined />} onClick={() => { setFolderTitle(selected.title); setFolderDialog({ id: selected.id }); }}>重命名</Button></div><div className="wiki-folder-actions"><Button type="primary" style={primary} icon={<PlusOutlined />} onClick={() => beginEdit(null, selected.id)}>新建文章</Button><Button onClick={() => { setFolderTitle(''); setFolderDialog({ parent_id: selected.id }); }}>新建子目录</Button>{selected.parent_id && <Button disabled={moving} onClick={() => move(selected.id, null)}>移回根目录</Button>}</div></div> : <div className="wiki-empty"><Empty image={Empty.PRESENTED_IMAGE_SIMPLE} description="选择一篇文章，或开始你的第一篇记录" /><Button type="primary" style={primary} icon={<PlusOutlined />} disabled={loading || !!error} onClick={() => beginEdit(null)}>新建文章</Button></div>}
      </main>);
  return <ConfigProvider getPopupContainer={popup} theme={{ token: { colorPrimary: '#00ab73', borderRadius: 5 }, components: { Tree: { nodeSelectedBg: '#e6f7f2', nodeSelectedColor: '#16211d', nodeHoverBg: '#f3faf6', titleHeight: 38 } } }}>
    <style>{css}</style>{msgHolder}{modalHolder}
    <section className="wiki" style={{ height: ctx.ui.sizing.available.height || undefined }} aria-label="个人 Wiki">
      {compact ? <>{content}<Drawer title="文档目录" closable={{ placement: 'end' }} placement="right" open={navigationOpen} onClose={() => setNavigationOpen(false)} getContainer={false} rootStyle={{ position: 'absolute' }} width="min(360px, 90%)" styles={{ body: { padding: 0, minHeight: 0 }, header: { padding: '16px' } }}><div id="wiki-navigation" style={{ height: '100%' }}>{navigation}</div></Drawer></> : <Splitter orientation="horizontal" style={{ height: '100%' }} onResize={sizes => setNavigationWidth(sizes[0])}>
        <Splitter.Panel size={navigationWidth} min={240} max="55%" style={{ overflow: 'hidden' }}>{navigation}</Splitter.Panel>
        <Splitter.Panel min={320} style={{ overflow: 'hidden' }}>{content}</Splitter.Panel>
      </Splitter>}
    </section>
    <Modal title={folderDialog?.id ? '重命名文件夹' : '新建文件夹'} open={!!folderDialog} onCancel={() => { if (!saving) setFolderDialog(null); }} onOk={saveFolder} confirmLoading={saving} okText="保存" cancelText="取消" okButtonProps={{ disabled: !folderTitle.trim() }}><Form layout="vertical"><Form.Item label="名称"><Input aria-label="文件夹名称" autoFocus placeholder="文件夹名称" value={folderTitle} maxLength={100} onChange={event => setFolderTitle(event.target.value)} onPressEnter={saveFolder} /></Form.Item>{!folderDialog?.id && <Form.Item label="位置"><Select aria-label="文件夹位置" value={folderDialog?.parent_id || "root"} onChange={value => setFolderDialog({ parent_id: value === "root" ? null : value })} options={[{ value: "root", label: "根目录" }, ...nodes.filter(node => node.node_type === "folder").map(node => ({ value: node.id, label: node.title }))]} /></Form.Item>}</Form></Modal>
    <Modal title="创建标签" open={tagDialog} onCancel={() => { if (!tagBusy) setTagDialog(false); }} onOk={createTag} confirmLoading={tagBusy} okText="创建" cancelText="取消" okButtonProps={{ disabled: !tagName.trim() }}>
      {tagError && <Alert title={tagError} type="error" showIcon />}
      <Form layout="vertical"><Form.Item label="名称" required><Input aria-label="标签名称" value={tagName} maxLength={40} onChange={event => setTagName(event.target.value)} /></Form.Item><Form.Item label="颜色"><Select aria-label="标签颜色" value={tagColor} onChange={setTagColor} options={[{ value: 'green', label: '薄荷绿' }, { value: 'blue', label: '浅蓝' }, { value: 'gold', label: '暖黄' }, { value: 'purple', label: '淡紫' }, { value: 'default', label: '灰色' }]} /></Form.Item><Form.Item label="说明"><Input.TextArea aria-label="标签说明" value={tagDescription} maxLength={200} onChange={event => setTagDescription(event.target.value)} /></Form.Item></Form>
    </Modal>
  </ConfigProvider>;
}
